$raw = Get-Content $file -Raw
# Extract just the source_code value
$match = [regex]::Match($raw, '"source_code"\s*:\s*"((?:[^"\\]|\\.)*)\"')
if ($match.Success) {
    $src = $match.Groups[1].Value -replace '\\r\\n', "`n" -replace '\\n', "`n" -replace '\\"', '"'
    $lines = $src -split "`n"
    Write-Host "Total lines: $($lines.Count)"
    # Find selection_changed
    for ($i=0; $i -lt $lines.Count; $i++) {
        if ($lines[$i] -imatch "selection|appl_event|eventid|register|NODE_SEL") {
            $start = [Math]::Max(0, $i-2); $end = [Math]::Min($lines.Count-1, $i+4)
            Write-Host "--- Line $($i+1) ---"
            $lines[$start..$end] | ForEach-Object { Write-Host $_ }
        }
    }
}

