306	function cellRefToColRow(ref) {
307	  const m = /^([A-Z]+)(\d+)$/.exec(ref);
308	  let col = 0;
309	  for (const ch of m[1]) col = col * 26 + (ch.charCodeAt(0) - 64);
310	  return { col: col - 1, row: parseInt(m[2], 10) - 1 };
311	}
