315	  const anchors = imgs.map((img, i) => {
316	    const { col, row } = cellRefToColRow(img.anchorCell);
317	    const cx = img.width * EMU_PER_PX, cy = img.height * EMU_PER_PX;
318	    return `<xdr:oneCellAnchor editAs="oneCell">
319	<xdr:from><xdr:col>${col}</xdr:col><xdr:colOff>0</xdr:colOff><xdr:row>${row}</xdr:row><xdr:rowOff>0</xdr:rowOff></xdr:from>
320	<xdr:ext cx="${cx}" cy="${cy}"/>
