323	<xdr:blipFill><a:blip r:embed="${img.rid}"/><a:stretch><a:fillRect/></a:stretch></xdr:blipFill>
324	<xdr:spPr><a:xfrm><a:off x="0" y="0"/><a:ext cx="${cx}" cy="${cy}"/></a:xfrm><a:prstGeom prst="rect"><a:avLst/></a:prstGeom></xdr:spPr>
325	</xdr:pic>
