539	// =============================================================
540	// appendProcessFlow — append a vertical flowchart below the data
541	//   table on a textSheet payload. Used by build() to decorate the
542	//   Processing Logic sheet automatically when PROCESS_FLOW is non-empty.
543	//
544	// Layout (3-col span = matches the ABAP Logic sheet's #/Event/Step grid):
545	//   row N+1   blank spacer
546	//   row N+2   "Process Flow Chart" heading       (style 17, A:C merged)
547	//   row N+3   first node (box / decision)        (A:C merged, ↓ stacked)
548	//   row N+4   "↓"                                 (style 25, no border)
549	//   row N+5   next node ...
550	//
551	// Node convention (each PROCESS_FLOW item is a single string):
552	//   · Plain text                → bordered box (style 21)
553	//   · Prefix '?' → decision       → yellow box (style 20), '?' stripped, '◇ ' added
554	//   · Prefix '!' → terminal/exit  → bordered box, '■ ' added (END / RETURN /
555	//                                   LEAVE LIST-PROCESSING markers)
556	//
557	// Decision branches that need a separate side-arm row are described inside
558	// the decision string itself with " → " (e.g. "? gt_result IS INITIAL → MESSAGE + LEAVE")
559	// — the renderer keeps everything on one row so the chart stays compact in
560	// a 3-column grid. For programs that need true two-branch fan-out, drivers
561	// can render the branch as the next node prefixed with "└─ " or similar.
562	// =============================================================
563	function appendProcessFlow(payload, items, opts = {}) {
564	  if (!Array.isArray(items) || items.length === 0) return payload;
565	  const { cells, merges, rowHeights, cols } = payload;
566	  const heading = opts.heading || 'Process Flow Chart';
567	  const colSpan = Math.max(1, Math.min(3, cols.length || 3));
568	  const lastCol = colLetter(colSpan - 1);
569	
570	  // Find next free row by scanning current cells.
571	  let maxRow = 0;
572	  for (const ref of Object.keys(cells)) {
573	    const m = /^([A-Z]+)(\d+)$/.exec(ref);
574	    if (m) maxRow = Math.max(maxRow, +m[2]);
575	  }
576	
577	  let r = maxRow + 2; // 1 blank spacer row between table and heading
578	
579	  // Heading row — style 17 (grey + bold + all borders).
580	  cells[R(r - 1, 0)] = { v: heading, s: 17 };
581	  for (let c = 1; c < colSpan; c++) cells[R(r - 1, c)] = { s: 17 };
582	  if (colSpan > 1) merges.push(`A${r}:${lastCol}${r}`);
583	  rowHeights[r] = 22;
584	  r++;
585	
586	  items.forEach((raw, idx) => {
587	    const txt = String(raw ?? '');
588	    const isDecision = /^\?\s*/.test(txt);
589	    const isTerminal = /^!\s*/.test(txt);
590	    const label = isDecision ? `◇ ${txt.replace(/^\?\s*/, '')}`
591	                : isTerminal ? `■ ${txt.replace(/^!\s*/, '')}`
592	                : txt;
593	    const style = isDecision ? 20 : 21;
594	
595	    cells[R(r - 1, 0)] = { v: label, s: style };
596	    for (let c = 1; c < colSpan; c++) cells[R(r - 1, c)] = { s: style };
597	    if (colSpan > 1) merges.push(`A${r}:${lastCol}${r}`);
598	    rowHeights[r] = 24;
599	    r++;
600	
601	    if (idx < items.length - 1) {
602	      // Centered "↓" arrow row, no border / no fill — visually links boxes.
603	      cells[R(r - 1, 0)] = { v: '↓', s: 25 };
604	      for (let c = 1; c < colSpan; c++) cells[R(r - 1, c)] = { s: 25 };
605	      if (colSpan > 1) merges.push(`A${r}:${lastCol}${r}`);
606	      rowHeights[r] = 16;
607	      r++;
608	    }
609	  });
610	
611	  return payload;
612	}
