759	// paramsBlock — append a "Parameters" table below existing sheet
760	//   content (e.g. under the wireframes drawn in screensSheet).
761	//
762	// Uses the same 17-col grid (A..Q) shared with screensSheet:
763	//   A        = left frame (style 9)
764	//   B:D      = Field       (header style 4 → data style 5)
765	//   E:F      = Type        (")
766	//   G:H      = Required    (")
767	//   I:K      = Default     (")
768	//   L:P      = Description (")
769	//   Q        = right frame (style 10)
770	//
771	// Rows:
772	//   row startRow      → merged A:Q title bar 'Parameters' (style 17)
773	//   row startRow+1    → header row (Field / Type / Required / Default / Description)
774	//   row startRow+2..  → one row per parameter
775	//
776	// Call AFTER drawing wireframes, ~1–2 rows below the last closing frame
777	// row, so the params table reads as a caption of the screen above.
778	//
779	// Returns the next free row number (1-based).
780	// =============================================================
781	function paramsBlock(cells, merges, rowHeights, startRow, params = []) {
782	  const COLS = [[1, 3], [4, 5], [6, 7], [8, 10], [11, 15]]; // B:D E:F G:H I:K L:P
783	  const HEADERS = ['Field', 'Type', 'Required', 'Default', 'Description'];
784	  let r = startRow;
785	
786	  // Title bar — merged A:Q, grey + bold.
787	  cells[R(r - 1, 0)] = { v: 'Parameters', s: 17 };
788	  for (let c = 1; c <= 16; c++) cells[R(r - 1, c)] = { s: 17 };
789	  merges.push(`A${r}:Q${r}`);
790	  rowHeights[r] = 20;
791	  r++;
792	
793	  // Header row — left/right frame + merged column groups.
794	  cells[R(r - 1, 0)] = { s: 9 };
795	  HEADERS.forEach((h, i) => {
796	    const [c0, c1] = COLS[i];
797	    cells[R(r - 1, c0)] = { v: h, s: 4 };
798	    for (let c = c0 + 1; c <= c1; c++) cells[R(r - 1, c)] = { s: 4 };
799	    merges.push(`${colLetter(c0)}${r}:${colLetter(c1)}${r}`);
800	  });
801	  cells[R(r - 1, 16)] = { s: 10 };
802	  r++;
803	
804	  // Data rows — empty array still leaves the header visible as a stub.
805	  for (const p of params) {
806	    cells[R(r - 1, 0)] = { s: 9 };
807	    const vals = [p.field, p.type, p.required, p.defaultVal, p.description];
808	    vals.forEach((v, i) => {
809	      const [c0, c1] = COLS[i];
810	      cells[R(r - 1, c0)] = { v: v ?? '', s: 5 };
811	      for (let c = c0 + 1; c <= c1; c++) cells[R(r - 1, c)] = { s: 5 };
812	      merges.push(`${colLetter(c0)}${r}:${colLetter(c1)}${r}`);
813	    });
814	    cells[R(r - 1, 16)] = { s: 10 };
815	    r++;
816	  }
817	
818	  return r;
819	}
