822	// Screen-sheet render helpers — kept for FALLBACK cell-border wireframes
823	// when no headless browser is available for image rasterization (v8).
824	//
825	// v8 note: the PRIMARY path for Selection + ALV is now embedded PNG
826	// images produced by scripts/spec/screen-image-renderer.mjs. These
827	// helpers are still used for:
828	//   · Flow diagram rows (grey styled)
829	//   · BAPI mapping rows (grey styled)
830	//   · Yellow warning rows at the BOTTOM of the sheet (style 20)
831	//   · Full fallback wireframe when rasterizer returns null
832	// =============================================================
833	function screenFrameRow(cells, row) {
834	  cells[R(row - 1, 0)]  = { s: 9 };   // col A — left border
835	  cells[R(row - 1, 16)] = { s: 10 };  // col Q — right border
836	}
837	function screenCloseFrame(cells, row) {
838	  cells[R(row - 1, 0)] = { s: 15 };                              // BL
839	  for (let c = 1; c <= 15; c++) cells[R(row - 1, c)] = { s: 12 }; // bottom only
840	  cells[R(row - 1, 16)] = { s: 16 };                              // BR
841	}
842	// Full-width row (A:Q merged) — use for sheet titles, section titles,
843	// standalone banners. Style applied to ALL cells so outer borders render.
844	function screenFullRow(cells, merges, row, val, s) {
845	  cells[R(row - 1, 0)] = { v: val, s };
846	  for (let c = 1; c <= 16; c++) cells[R(row - 1, c)] = { s };
847	  merges.push(`A${row}:Q${row}`);
848	}
849	// Sub-title INSIDE a frame section. Keeps col A/Q frame borders intact
850	// (A=9, Q=10) and merges B:P for the label. Style applied to every cell
851	// in the B:P merge so borders render if the style carries any.
852	function screenSubtitleRow(cells, merges, row, val, s = 1) {
853	  cells[R(row - 1, 0)]  = { s: 9 };
854	  cells[R(row - 1, 1)]  = { v: val, s };
855	  for (let c = 2; c <= 15; c++) cells[R(row - 1, c)] = { s };
856	  cells[R(row - 1, 16)] = { s: 10 };
857	  merges.push(`B${row}:P${row}`);
858	}
859	// Merged cell whose outer rectangle renders — style set on every cell in
860	// the merge range so Excel draws the full perimeter (critical for input
861	// boxes F:H / K:M which otherwise lose their right+bottom edges).
862	function screenMerge(cells, merges, row, c0, c1, style, value) {
863	  cells[R(row - 1, c0)] = { v: value ?? '', s: style };
864	  for (let c = c0 + 1; c <= c1; c++) cells[R(row - 1, c)] = { s: style };
865	  if (c1 > c0) merges.push(`${colLetter(c0)}${row}:${colLetter(c1)}${row}`);
866	}
