924	// ALV-layout wireframe, rendered as cell-border rows. Columns distribute
925	// evenly across B..P (15 cells of 14-unit width each = 210 units total).
926	// Header = style 4 (grey bordered), data = style 5 (bordered).
927	function renderAlvWireframe(cells, merges, rowHeights, startRow, spec) {
928	  const columns = spec.columns || [];
929	  const sampleRows = (spec.sampleRows || []).slice(0, Math.max(1, Math.min(spec.maxRows || 3, 5)));
930	  let r = startRow;
931	
932	  // Title bar.
933	  screenFullRow(cells, merges, r, '◆ ALV 그리드', 17);
934	  rowHeights[r] = 20;
935	  r++;
936	
937	  const layout = distributeAlvColumns(columns.length);
938	  if (!layout.length) {
939	    screenCloseFrame(cells, r);
940	    return r + 1;
941	  }
942	
943	  // Header row.
944	  screenFrameRow(cells, r);
945	  columns.forEach((c, i) => {
946	    const [c0, c1] = layout[i];
947	    screenMerge(cells, merges, r, c0, c1, 4, c.header || c.name || '');
948	  });
949	  rowHeights[r] = 20;
950	  r++;
951	
952	  // Sample data rows — capped at maxRows (default 3, absolute max 5).
953	  for (const row of sampleRows) {
954	    screenFrameRow(cells, r);
955	    columns.forEach((c, i) => {
956	      const [c0, c1] = layout[i];
957	      const v = row[c.name];
958	      screenMerge(cells, merges, r, c0, c1, 5, v == null ? '' : String(v));
959	    });
960	    rowHeights[r] = 18;
961	    r++;
962	  }
963	
964	  screenCloseFrame(cells, r);
965	  return r + 1;
966	}
