968	// Distribute N columns across cells 1..15 (B:P). Returns [[c0,c1], ...].
969	// Extra cells prepended to leading columns so widest-header columns (usually
970	// placed first) get the extra real estate.
971	function distributeAlvColumns(n) {
972	  if (n <= 0) return [];
973	  const total = 15;
974	  const base = Math.floor(total / n);
975	  const extra = total - base * n;
976	  const out = [];
977	  let c = 1;
978	  for (let i = 0; i < n; i++) {
979	    const width = base + (i < extra ? 1 : 0);
980	    out.push([c, c + width - 1]);
981	    c += width;
982	  }
983	  return out;
984	}
